Rule.Source:
import javax.naming.directory.DirContext;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.Link;

String APP_NAME = "LDAP ApacheDS";

if (identityName == null || action == null) {
    return "ERROR: identityName and action are required";
}
boolean disable = "Disable".equalsIgnoreCase(action);
if (!disable && !"Enable".equalsIgnoreCase(action)) {
    return "ERROR: action must be Disable or Enable, not " + action;
}

Identity identity = context.getObjectByName(Identity.class, identityName);
if (identity == null) return "ERROR: identity " + identityName + " not found";
Application app = context.getObjectByName(Application.class, APP_NAME);
if (app == null) return "ERROR: application " + APP_NAME + " not found";

Link link = identity.getLink(app);
if (link == null) {
    return "SKIPPED " + identityName + ": no LDAP ApacheDS account";
}
String dn = link.getNativeIdentity();

DirContext ldap = ldapConnect(context, app);
try {
    ldapSetDisabled(ldap, dn, disable);
} finally {
    ldap.close();
}

// Reflect it in IIQ straight away
link.setAttribute("accountStatus", disable ? "Disabled" : "Active");
link.setAttribute("pwdAccountLockedTime", disable ? "000001010000Z" : null);
link.setAttribute("IIQDisabled", Boolean.valueOf(disable));
context.saveObject(link);
context.commitTransaction();

String msg = (disable ? "DISABLED " : "ENABLED ") + identityName + ": " + dn;
log.info("LDAP ApacheDS: " + msg);
return msg;
